"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface PartyPopperIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface PartyPopperIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const PartyPopperIcon = forwardRef<PartyPopperIconHandle, PartyPopperIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const popperVariants: Variants = {
   normal: { rotate: 0, scale: 1 },
   animate: {
    rotate: [0, -10, 4, 0],
    scale: [1, 0.9, 1.04, 1],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     times: [0, 0.3, 0.6, 1],
    },
   },
  };

  const confettiVariants: Variants = {
   normal: { scale: 1, opacity: 1 },
   animate: (i: number) => ({
    scale: [0, 1.08, 1],
    opacity: [0, 1, 1],
    transition: {
     duration: 0.5 * duration,
     ease: "easeOut",
     times: [0, 0.7, 1],
     delay: (0.18 + i * 0.05) * duration,
    },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.g
       variants={popperVariants}
       style={{ transformBox: "view-box", originX: "2px", originY: "22px" }}
      >
       <path d="M5.8 11.3 2 22l10.7-3.79" />
       <path d="M11 13c1.93 1.93 2.83 4.17 2 5-.83.83-3.07-.07-5-2-1.93-1.93-2.83-4.17-2-5 .83-.83 3.07.07 5 2Z" />
      </m.g>
      <m.path
       d="m11 2 .33.82c.34.86-.2 1.82-1.11 1.98C9.52 4.9 9 5.52 9 6.23V7"
       variants={confettiVariants}
       custom={0}
       style={{ transformBox: "view-box", originX: "9.5px", originY: "14.5px" }}
      />
      <m.path
       d="m22 2-2.24.75a2.9 2.9 0 0 0-1.96 3.12c.1.86-.57 1.63-1.45 1.63h-.38c-.86 0-1.6.6-1.76 1.44L14 10"
       variants={confettiVariants}
       custom={1}
       style={{ transformBox: "view-box", originX: "9.5px", originY: "14.5px" }}
      />
      <m.path
       d="m22 13-.82-.33c-.86-.34-1.82.2-1.98 1.11c-.11.7-.72 1.22-1.43 1.22H17"
       variants={confettiVariants}
       custom={2}
       style={{ transformBox: "view-box", originX: "9.5px", originY: "14.5px" }}
      />
      <m.path
       d="M4 3h.01"
       variants={confettiVariants}
       custom={3}
       style={{ transformBox: "view-box", originX: "9.5px", originY: "14.5px" }}
      />
      <m.path
       d="M15 2h.01"
       variants={confettiVariants}
       custom={4}
       style={{ transformBox: "view-box", originX: "9.5px", originY: "14.5px" }}
      />
      <m.path
       d="M22 8h.01"
       variants={confettiVariants}
       custom={5}
       style={{ transformBox: "view-box", originX: "9.5px", originY: "14.5px" }}
      />
      <m.path
       d="M22 20h.01"
       variants={confettiVariants}
       custom={6}
       style={{ transformBox: "view-box", originX: "9.5px", originY: "14.5px" }}
      />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

PartyPopperIcon.displayName = "PartyPopperIcon";
export { PartyPopperIcon };
